class Solution { public int cutOffTree(List<List<Integer>> forest){List<int[]> trees=new ArrayList<>();for(int r=0;r<forest.size();r++)for(int c=0;c<forest.get(0).size();c++)if(forest.get(r).get(c)>1)trees.add(new int[]{forest.get(r).get(c),r,c});trees.sort(Comparator.comparingInt(tree->tree[0]));int row=0,column=0,total=0;for(int[] tree:trees){int distance=bfs(forest,row,column,tree[1],tree[2]);if(distance<0)return -1;total+=distance;row=tree[1];column=tree[2];}return total;}private int bfs(List<List<Integer>> forest,int sr,int sc,int tr,int tc){if(sr==tr&&sc==tc)return 0;int rows=forest.size(),columns=forest.get(0).size();boolean[][] seen=new boolean[rows][columns];Queue<int[]> queue=new ArrayDeque<>();queue.offer(new int[]{sr,sc});seen[sr][sc]=true;int steps=0;int[][] directions={{1,0},{-1,0},{0,1},{0,-1}};while(!queue.isEmpty()){steps++;for(int size=queue.size();size>0;size--){int[] cell=queue.poll();for(int[] d:directions){int r=cell[0]+d[0],c=cell[1]+d[1];if(r<0||r>=rows||c<0||c>=columns||seen[r][c]||forest.get(r).get(c)==0)continue;if(r==tr&&c==tc)return steps;seen[r][c]=true;queue.offer(new int[]{r,c});}}}return -1;} }
